 INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Fehlerbehebung > Hardware-Fehler
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Hardware-Fehler immer ohne Diagnosewerkzeuge behoben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Werkzeuge helfen, Fehler zu identifizieren"}, {"text": "Ja", "correct": false, "because": "Diagnose oft notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Hardware-Fehler immer durch Austausch der Komponente behoben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Reparaturen oder Einstellungen können ausreichen"}, {"text": "Ja", "correct": false, "because": "Nicht immer Austausch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Hardware-Fehler die Funktion eines gesamten Systems beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Defekte Teile können Systemausfälle verursachen"}, {"text": "Nein", "correct": false, "because": "Einfluss ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Fehlerbehebung bei Hardware-Fehlern unabhängig von der Garantie möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Fehler können auch außerhalb der Garantie behoben werden"}, {"text": "Nein", "correct": false, "because": "Garantie ist keine Voraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Hardware-Fehler durch Software-Updates verursacht werden?', 2, '[{"text": "Nein", "correct": true, "because": "Hardware-Fehler sind physisch, nicht softwarebasiert"}, {"text": "Ja", "correct": false, "because": "Software beeinflusst Hardware nicht direkt"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Fehlerbehebung von Hardware-Fehlern am wichtigsten?', 3, '[{"text": "Diagnose", "correct": true, "because": "Identifiziert die Fehlerursache"}, {"text": "Austausch", "correct": false, "because": "Späterer Schritt"}, {"text": "Neustart", "correct": false, "because": "Nicht immer effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird häufig zur Diagnose von Hardware-Fehlern verwendet?', 2, '[{"text": "Multimeter", "correct": true, "because": "Misst Spannung und Kontinuität"}, {"text": "Texteditor", "correct": false, "because": "Für Software, nicht Hardware"}, {"text": "Browser", "correct": false, "because": "Irrelevant für Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente ist am häufigsten von Hardware-Fehlern betroffen?', 2, '[{"text": "Festplatte", "correct": true, "because": "Bewegliche Teile und hohe Nutzung"}, {"text": "Monitor", "correct": false, "because": "Weniger anfällig"}, {"text": "Tastatur", "correct": false, "because": "Robuster"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein häufiges Symptom für einen Hardware-Fehler?', 3, '[{"text": "Systemabsturz", "correct": true, "because": "Zeigt Defekt oder Inkompatibilität"}, {"text": "Langsame Internetverbindung", "correct": false, "because": "Netzwerkproblem"}, {"text": "Softwarefehlermeldung", "correct": false, "because": "Softwarebezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft oft bei der ersten Fehlerbehebung?', 2, '[{"text": "Neustart des Systems", "correct": true, "because": "Löst temporäre Probleme"}, {"text": "Komplettausbau", "correct": false, "because": "Zu aufwendig"}, {"text": "Software-Update", "correct": false, "because": "Nicht hardwarebezogen"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Fehlerbehebung von Hardware-Fehlern typisch?', 4, '[{"text": "Diagnose", "correct": true, "because": "Fehler identifizieren"}, {"text": "Testen", "correct": true, "because": "Funktion prüfen"}, {"text": "Reparatur oder Austausch", "correct": true, "because": "Fehler beheben"}, {"text": "Neuinstallation des Betriebssystems", "correct": false, "because": "Softwarelösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symptome deuten auf Hardware-Fehler hin?', 3, '[{"text": "Bluescreen", "correct": true, "because": "Hardware- oder Treiberproblem"}, {"text": "Ungewöhnliche Geräusche", "correct": true, "because": "Mechanischer Defekt"}, {"text": "Systemstartfehler", "correct": true, "because": "Hardwareausfall"}, {"text": "Langsame Software", "correct": false, "because": "Softwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge helfen bei der Fehlerbehebung von Hardware-Fehlern?', 3, '[{"text": "Multimeter", "correct": true, "because": "Misst elektrische Werte"}, {"text": "Diagnosesoftware", "correct": true, "because": "Prüft Komponenten"}, {"text": "Ersatzteile", "correct": true, "because": "Zum Testen"}, {"text": "Textverarbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursachen können Hardware-Fehler haben?', 4, '[{"text": "Physischer Defekt", "correct": true, "because": "Verschleiß oder Bruch"}, {"text": "Überhitzung", "correct": true, "because": "Schadet Komponenten"}, {"text": "Stromschwankungen", "correct": true, "because": "Beeinträchtigt Funktion"}, {"text": "Softwarefehler", "correct": false, "because": "Nicht hardwarebezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind oft von Hardware-Fehlern betroffen?', 3, '[{"text": "Festplatte", "correct": true, "because": "Mechanische Teile anfällig"}, {"text": "Netzteil", "correct": true, "because": "Stromversorgung kritisch"}, {"text": "Arbeitsspeicher", "correct": true, "because": "Fehler führen zu Abstürzen"}, {"text": "Monitor", "correct": false, "because": "Weniger häufig"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Bluescreen kann auf einen Hardware-Fehler hinweisen. b) Hardware-Fehler lassen sich immer ohne Werkzeuge beheben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bluescreen ja, Werkzeuge oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Überhitzung kann Hardware-Fehler verursachen. b) Ein Neustart behebt alle Hardware-Probleme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überhitzung ja, Neustart nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Multimeter hilft bei der Diagnose von Hardware-Fehlern. b) Hardware-Fehler betreffen nur den Prozessor.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Multimeter ja, Fehler vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Festplattenfehler können Datenverlust verursachen. b) Hardware-Fehler sind immer sofort sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenverlust ja, Fehler nicht immer offensichtlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hardware-Fehler können durch Tests identifiziert werden. b) Ein defektes Netzteil beeinträchtigt das System nicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests ja, Netzteil kritisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

